function runMacro(name, args) {
    if (mock && isCallable(mock.run)) return mock.run(name, args);
    const host = stand();
    if (host !== null) return host.runMacro(name, args);
    connect();
    if (noExcel) return stand().runMacro(name, args);
    const target = `'${String(get(book, "Name")).replace(/'/g, "''")}'!${name}`;
    return call(app, "Run", [target, ...args]);
}

// ---------------------------------------------------------------------------- application state (spec §10)

const APP_ITEMS = [
    ["ScreenUpdating", false],
    ["EnableEvents", false],
    ["Calculation", -4135 /* xlCalculationManual */],
    ["DisplayAlerts", false],
    ["StatusBar", null],
    ["Cursor", 2 /* xlWait */],
    ["Interactive", false],
];
const appDepth = [0, 0, 0, 0, 0, 0, 0];
const appSaved = [];

function appSet(i, restore) {
    // Setting application properties can fail (e.g. Calculation without an open workbook).
    try {
        const a = application();
        const [prop, value] = APP_ITEMS[i];
        if (i === 4) {
            if (restore) put(a, prop, false);
        } else if (restore) {
            put(a, prop, appSaved[i]);
        } else {
            appSaved[i] = get(a, prop);
            put(a, prop, value);
        }
    } catch {
        // ignored, as in the VBA run time
    }
}
