        const full = String(pattern);
        const name = path.basename(full);
        const folder = path.dirname(full);
        const re = new RegExp(`^${name.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*").replace(/\?/g, ".")}$`, "i");
